<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class GoogleAnalyticsConnector extends AbstractConnector {public function id():string{return 'google_analytics';}public function label():string{return 'Google Analytics 4';}public function actions():array{return [new ConnectorAction('run_report','Run a GA4 Data API report for a property.',RiskLevel::Read,['type'=>'object','properties'=>['property_id'=>['type'=>'string'],'dateRanges'=>['type'=>'array'],'dimensions'=>['type'=>'array'],'metrics'=>['type'=>'array'],'limit'=>['type'=>'string']],'required'=>['property_id','dateRanges','metrics']])];}public function configurationSchema():array{return ['credentials'=>['access_token'=>['type'=>'password','required'=>true]],'fields'=>[]];}private function req(ConnectorConnection $c){return $this->client(['Authorization'=>'Bearer '.$this->bearer($c,'access_token')]);}public function test(ConnectorConnection $c):bool{try{$pid=(string)(($c->configuration??[])['property_id']??'');return $pid!==''&&$this->req($c)->get('https://analyticsdata.googleapis.com/v1beta/properties/'.$pid.'/metadata')->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);$property=(string)$a['property_id'];unset($a['property_id']);return ConnectorResult::success($this->req($c)->post('https://analyticsdata.googleapis.com/v1beta/properties/'.rawurlencode($property).':runReport',$a)->throw()->json());}}
